#define NCANON  ((int)(sizeof ucd_canon  / sizeof ucd_canon[0]))
#define NCOMPAT ((int)(sizeof ucd_compat / sizeof ucd_compat[0]))
#define NCLASS  ((int)(sizeof ucd_class  / sizeof ucd_class[0]))
#define NCOMP   ((int)(sizeof ucd_comp   / sizeof ucd_comp[0]))

/* Hangul, per section 3.12 of the standard. */
#define HSBASE 0xAC00
#define HLBASE 0x1100
#define HVBASE 0x1161
#define HTBASE 0x11A7
#define HLCOUNT 19
#define HVCOUNT 21
#define HTCOUNT 28
#define HNCOUNT (HVCOUNT * HTCOUNT)
#define HSCOUNT (HLCOUNT * HNCOUNT)

static const UDecomp *canon_find(uint32 cp)
{
    if (cp > 0xFFFF) return NULL;
    int lo = 0, hi = NCANON - 1;
    while (lo <= hi) {
        int m = (lo + hi) / 2;
        if (ucd_canon[m].cp == cp) return &ucd_canon[m];
        if (ucd_canon[m].cp < cp) lo = m + 1; else hi = m - 1;
    }
    return NULL;
}

static const UCompat *compat_find(uint32 cp)
{
    if (cp > 0xFFFF) return NULL;
    int lo = 0, hi = NCOMPAT - 1;
    while (lo <= hi) {
        int m = (lo + hi) / 2;
        if (ucd_compat[m].cp == cp) return &ucd_compat[m];
        if (ucd_compat[m].cp < cp) lo = m + 1; else hi = m - 1;
    }
    return NULL;
}

int unicode_combining_class(uint32 cp)
{
    if (cp > 0xFFFF) return 0;
    int lo = 0, hi = NCLASS - 1;
    while (lo <= hi) {
        int m = (lo + hi) / 2;
        if (ucd_class[m].cp == cp) return ucd_class[m].ccc;
        if (ucd_class[m].cp < cp) lo = m + 1; else hi = m - 1;
    }
    return 0;
}

static uint32 pair_compose(uint32 a, uint32 b)
{
    /* Hangul first */
    if (a >= HLBASE && a < HLBASE + HLCOUNT && b >= HVBASE && b < HVBASE + HVCOUNT)
        return HSBASE + (((a - HLBASE) * HVCOUNT) + (b - HVBASE)) * HTCOUNT;
    if (a >= HSBASE && a < HSBASE + HSCOUNT && (a - HSBASE) % HTCOUNT == 0 &&
        b > HTBASE && b < HTBASE + HTCOUNT)
        return a + (b - HTBASE);
    if (a > 0xFFFF || b > 0xFFFF) return 0;
    int lo = 0, hi = NCOMP - 1;
    while (lo <= hi) {
        int m = (lo + hi) / 2;
        uint32 ma = ucd_comp[m].a, mb = ucd_comp[m].b;
        if (ma == a && mb == b) return ucd_comp[m].cp;
        if (ma < a || (ma == a && mb < b)) lo = m + 1; else hi = m - 1;
    }
    return 0;
}

/* ------------------------------------------------------------ UTF-8 codec */
static int utf8_decode(const unsigned char *p, size_t len, uint32 *out)
{
    unsigned char c = p[0];
    if (c < 0x80) { *out = c; return 1; }
    if ((c & 0xE0) == 0xC0 && len >= 2 && (p[1] & 0xC0) == 0x80) {
        *out = ((uint32)(c & 0x1F) << 6) | (p[1] & 0x3F);
        return 2;
    }
    if ((c & 0xF0) == 0xE0 && len >= 3 && (p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80) {
        *out = ((uint32)(c & 0x0F) << 12) | ((uint32)(p[1] & 0x3F) << 6) | (p[2] & 0x3F);
        return 3;
    }
    if ((c & 0xF8) == 0xF0 && len >= 4 && (p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80 &&
        (p[3] & 0xC0) == 0x80) {
        *out = ((uint32)(c & 0x07) << 18) | ((uint32)(p[1] & 0x3F) << 12) |
               ((uint32)(p[2] & 0x3F) << 6) | (p[3] & 0x3F);
        return 4;
    }
    *out = c;                       /* not valid UTF-8: keep the byte */
    return 1;
}

static void utf8_encode(Buf *b, uint32 cp)
{
    if (cp < 0x80) buf_addc(b, (char)cp);
    else if (cp < 0x800) { buf_addc(b, (char)(0xC0 | (cp >> 6)));
                           buf_addc(b, (char)(0x80 | (cp & 0x3F))); }
    else if (cp < 0x10000) { buf_addc(b, (char)(0xE0 | (cp >> 12)));
                             buf_addc(b, (char)(0x80 | ((cp >> 6) & 0x3F)));
                             buf_addc(b, (char)(0x80 | (cp & 0x3F))); }
    else { buf_addc(b, (char)(0xF0 | (cp >> 18)));
           buf_addc(b, (char)(0x80 | ((cp >> 12) & 0x3F)));
           buf_addc(b, (char)(0x80 | ((cp >> 6) & 0x3F)));
           buf_addc(b, (char)(0x80 | (cp & 0x3F))); }
}

/* ------------------------------------------------------------- decompose */
typedef struct { uint32 *v; int n, cap; } CpVec;

static void cpv_add(CpVec *c, uint32 cp)
{
    if (c->n == c->cap) { c->cap = c->cap ? c->cap * 2 : 32;
                          c->v = xrealloc(c->v, (size_t)c->cap * sizeof(uint32)); }
    c->v[c->n++] = cp;
}

static void decompose_one(CpVec *out, uint32 cp, bool compat)
{
    if (cp >= HSBASE && cp < HSBASE + HSCOUNT) {
        uint32 si = cp - HSBASE;
        cpv_add(out, HLBASE + si / HNCOUNT);
        cpv_add(out, HVBASE + (si % HNCOUNT) / HTCOUNT);
        if (si % HTCOUNT) cpv_add(out, HTBASE + si % HTCOUNT);
        return;
    }
    const UDecomp *d = canon_find(cp);
    if (d) {
        decompose_one(out, d->a, compat);
        if (d->b) decompose_one(out, d->b, compat);
        return;
    }
    if (compat) {
        const UCompat *k = compat_find(cp);
        if (k) {
            for (int i = 0; i < k->n; i++)
                decompose_one(out, ucd_compat_seq[k->off + i], compat);
            return;
        }
    }
    cpv_add(out, cp);
}

/* form: 0 NFC, 1 NFD, 2 NFKC, 3 NFKD */
char *unicode_normalize(const char *s, size_t len, int form)
{
    bool compat = (form == 2 || form == 3);
    bool compose = (form == 0 || form == 2);
    CpVec c; memset(&c, 0, sizeof c);
    for (size_t i = 0; i < len; ) {
        uint32 cp;
        int adv = utf8_decode((const unsigned char *)s + i, len - i, &cp);
        decompose_one(&c, cp, compat);
        i += (size_t)adv;
    }
    /* canonical ordering: a stable sort of each run of combining marks */
    for (int i = 1; i < c.n; i++) {
        int cci = unicode_combining_class(c.v[i]);
        if (cci == 0) continue;
        int j = i;
        while (j > 0) {
            int ccp = unicode_combining_class(c.v[j-1]);
            if (ccp == 0 || ccp <= cci) break;
            uint32 t = c.v[j-1]; c.v[j-1] = c.v[j]; c.v[j] = t;
            j--;
        }
    }
    if (compose && c.n > 0) {
        int starter = 0, cpos = 1;
        uint32 sch = c.v[0];
        int lastcls = unicode_combining_class(sch);
        if (lastcls != 0) lastcls = 256;
        for (int i = 1; i < c.n; i++) {
            uint32 ch = c.v[i];
            int cls = unicode_combining_class(ch);
            uint32 comp = pair_compose(sch, ch);
            if (comp && (lastcls < cls || lastcls == 0)) {
                c.v[starter] = comp;
                sch = comp;
            } else {
                if (cls == 0) { starter = cpos; sch = ch; }
                lastcls = cls;
                c.v[cpos++] = ch;
            }
        }
        c.n = cpos;
    }
    Buf b; buf_init(&b);
    for (int i = 0; i < c.n; i++) utf8_encode(&b, c.v[i]);
    free(c.v);
    return buf_steal(&b);
}

bool unicode_is_normalized(const char *s, size_t len, int form)
{
    char *n = unicode_normalize(s, len, form);
    bool same = (strlen(n) == len) && memcmp(n, s, len) == 0;
    free(n);
    return same;
}
